namespace Kkdev92.Jev;

/// <summary>Controls the origin Authorization header generated by Jev.</summary>
public enum JevAuthenticationMode
{
    /// <summary>Obtain an API key for every attempt and send it as a bearer token.</summary>
    ApiKey = 0,

    /// <summary>Send no SDK-generated authorization. Custom handlers and other headers remain caller-owned.</summary>
    None = 1,
}
